export type TechId = keyof typeof TECH;

export type TechGroup = { label: string; items: Array<TechId | { name: string; icon: "workflow" }> };

/**
 * Everything shown in the Technology section. Remove any item we don't use,
 * or add new ones by id (see TECH above).
 */
export const techGroups: TechGroup[] = [
  { label: "Frontend", items: ["react", "nextjs", "angular", "typescript", "javascript", "html5", "css3", "tailwind"] },
  { label: "Mobile", items: ["reactnative", "expo", "flutter", "swift"] },
  { label: "Backend", items: ["nodejs", "express", "nestjs", "python", "dotnet"] },
  { label: "Data & APIs", items: ["postgresql", "mysql", "mongodb", "redis", "firebase", "supabase", "graphql", "prisma"] },
  { label: "Cloud & DevOps", items: ["aws", "azure", "docker", "git", "github", { name: "CI/CD", icon: "workflow" }] },
  { label: "Design & content", items: ["figma", "canva"] },
  { label: "Social platforms", items: ["facebook", "instagram", "linkedin", "youtube", "tiktok", "whatsapp"] },
];

/** Logos shown in the scrolling strip under the hero. */
export const marqueeTech: TechId[] = [
  "react", "nextjs", "angular", "typescript", "reactnative", "flutter", "nodejs", "python", "dotnet",
  "postgresql", "mysql", "mongodb", "firebase", "aws", "azure", "docker", "figma", "canva",
];

/** Map a project tag (e.g. ".NET 9", "React Native") to a logo when we have one. */
export function techForTag(tag: string): (typeof TECH)[TechId] | undefined {
  const t = tag.toLowerCase();
  if (t.startsWith("react native")) return TECH.reactnative;
  if (t.startsWith(".net")) return TECH.dotnet;
  if (t === "react") return TECH.react;
  if (t === "next.js") return TECH.nextjs;
  if (t === "prisma") return TECH.prisma;
  if (t === "aws") return TECH.aws;
  return undefined;
}
